      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      align-items: center;
      margin-bottom: 0.5rem;
    }
    h3 {
      margin: 0.5rem 0 0.25rem;
      font-size: 1rem;
    }
    .error {
      color: #a40000;

